import {cropImage} from './image-editor.js';
import {escapeHtml as e,avatar,themeClass,themes,symbols,tagList,uiIcons,imageSrc} from './ui.js';
export function profileMarkup(p,{own=false,preview=false}={}){
 const bannerPhoto=p.removeBanner?'':imageSrc(p.bannerUpload||p.bannerImage);const banner=['orbit','grid','waves'].includes(p.banner)?p.banner:'orbit';
 return `<section class="creator-profile ${themeClass(p)} ${preview?'profile-preview':''}"><div class="creator-banner banner-${banner}">${bannerPhoto?`<img class="creator-banner-image" src="${e(bannerPhoto)}" alt="Profilbanner" decoding="async">`:`<div class="banner-lines" aria-hidden="true"></div><span class="banner-emblem" aria-hidden="true">${e(symbols[p.avatar]||'✦')}</span>`}${p.demo?'<span class="demo-badge">Demo-Profil</span>':''}</div><div class="creator-content"><div class="creator-top">${avatar(p,'creator-avatar')}${own?'<button class="secondary" id="editProfile">Profil bearbeiten</button>':''}</div><div class="creator-name"><h1>${e(p.name||'Dein Name')}</h1>${p.pronouns?`<span>${e(p.pronouns)}</span>`:''}</div><div class="creator-handle">${p.username?'@'+e(p.username):''}</div><div class="creator-role">${e(p.role||'VTuber')}${p.collab?'<span class="availability"><i></i> Offen für Collabs</span>':''}</div><p class="creator-bio">${e(p.bio||'Erzähl, was dich und deinen Stream besonders macht.')}</p><div class="interest-pills">${tagList(p.tags).map(t=>`<span>${e(t)}</span>`).join('')}</div><div class="creator-facts">${p.languages?`<div><span>◎</span><p><small>Sprachen</small>${e(p.languages)}</p></div>`:''}${p.schedule?`<div><span>◷</span><p><small>Stream-Zeiten</small>${e(p.schedule)}</p></div>`:''}</div>${p.collab&&p.formats?`<div class="collab-block"><span>✧</span><div><h3>Lass uns etwas zusammen machen.</h3><p>${e(p.formats)}</p></div></div>`:''}<div class="creator-links">${[['Website',p.link,'↗'],['Twitch',p.twitch,'◈'],['YouTube',p.youtube,'▷'],['Social',p.social,'◎']].filter(([,url])=>url).map(([label,url,icon])=>`<a href="${e(url)}" target="_blank" rel="noopener noreferrer"><span>${icon}</span><strong>${label}</strong><span>↗</span></a>`).join('')}</div>${own?'<button class="logout mobile-logout" id="logoutProfile">Abmelden</button>':''}</div></section>`;
}
const input=(key,label,placeholder,max=100,type='text')=>`<label class="editor-label">${label}<input name="${key}" type="${type}" maxlength="${max}" placeholder="${placeholder}" ${key==='name'?'required':''}></label>`;
export function openProfileEditor({profile,onSave,initialTab='identity'}){
 const dialog=document.querySelector('#profileDialog');
 dialog.innerHTML=`<form id="profileEditor" novalidate><div class="editor-header"><div><span class="eyebrow">DEIN AUFTRITT</span><h2>Mach dein Profil zu deinem.</h2></div><button type="button" class="icon-control editor-close" aria-label="Profilbearbeitung schließen">${uiIcons.close}</button></div><div class="editor-grid"><div class="editor-controls"><div class="editor-tabs" role="tablist" aria-label="Profilbereiche">${[['identity','Über dich'],['design','Design'],['collab','Collabs'],['links','Links']].map(([id,label],i)=>`<button type="button" role="tab" aria-selected="${i===0}" aria-controls="editor-${id}" id="tab-${id}" data-editor-tab="${id}">${label}</button>`).join('')}</div><div class="editor-panel" id="editor-identity" role="tabpanel" aria-labelledby="tab-identity">${input('name','Anzeigename','Dein VTuber-Name',40)}<label class="editor-label">Nutzername · eindeutig<div class="username-input"><span>@</span><input name="username" required minlength="3" maxlength="24" pattern="[A-Za-z0-9_]{3,24}" placeholder="dein_username" autocomplete="username" autocapitalize="none" spellcheck="false"></div><small>3–24 Buchstaben, Zahlen oder Unterstriche. Dein Anzeigename kann davon abweichen.</small></label><div class="editor-columns"><label class="editor-label">Rolle<select name="role"><option>VTuber</option><option>Zuschauer</option></select></label>${input('pronouns','Pronomen · optional','z. B. sie/ihr',30)}</div><label class="editor-label">Über dich<textarea name="bio" maxlength="280" placeholder="Was macht deinen Stream besonders?"></textarea><small>Bis zu 280 Zeichen</small></label>${input('tags','Interessen & Games','Cozy Games, Art, Minecraft',100)}<p class="field-note">Mit Kommas trennen. Deine Interessen helfen bei Empfehlungen.</p>${input('languages','Sprachen','Deutsch, Englisch',100)}${input('schedule','Stream-Zeiten · optional','Di & Do ab 19 Uhr · Europe/Berlin',120)}</div><div class="editor-panel" id="editor-design" role="tabpanel" aria-labelledby="tab-design" hidden><div class="image-upload-section"><h3>Deine Bilder</h3><p>PNG, JPG oder WebP · Original bis 8 MB · Auf deinem Profil öffentlich sichtbar</p><div class="upload-row"><div><strong>Profilbild</strong><small id="avatarImageStatus">Eigenes Bild statt Symbol</small></div><label class="upload-label"><input id="avatarFile" type="file" accept="image/png,image/jpeg,image/webp"><span>Bild wählen ↗</span></label><button type="button" class="remove-image" id="removeAvatar">Entfernen</button></div><div class="upload-row"><div><strong>Profilbanner</strong><small id="bannerImageStatus">Dein Titelbild im Format 3:1</small></div><label class="upload-label"><input id="bannerFile" type="file" accept="image/png,image/jpeg,image/webp"><span>Bild wählen ↗</span></label><button type="button" class="remove-image" id="removeBanner">Entfernen</button></div></div><h3>Deine Farben</h3><p>Ein durchgängiger Look für Profil, Avatar und Karten.</p><div class="theme-picker">${themes.map((t,i)=>`<label class="theme-choice theme-${t}"><input type="radio" name="theme" value="${t}"><span></span><small>${['Lilac','Ocean','Rose','Forest','Sunset','Mono'][i]}</small></label>`).join('')}</div><h3>Dein Avatar</h3><p>Initiale oder Symbol — passend zu deinem Stil.</p><div class="avatar-picker">${Object.entries(symbols).map(([key,s])=>`<label><input type="radio" name="avatar" value="${key}"><span>${s||'Aa'}</span><small class="sr-only">${key}</small></label>`).join('')}</div><h3>Dein Banner</h3><div class="banner-picker">${[['orbit','Orbit'],['grid','Grid'],['waves','Waves']].map(([key,label])=>`<label><input type="radio" name="banner" value="${key}"><span class="banner-${key}"><i class="banner-lines"></i></span><small>${label}</small></label>`).join('')}</div></div><div class="editor-panel" id="editor-collab" role="tabpanel" aria-labelledby="tab-collab" hidden><div class="collab-editor-intro">✧<h3>Der nächste Stream? Zusammen.</h3><p>Zeig anderen Creatorn, wofür du offen bist.</p></div><label class="collab-toggle"><span><strong>Offen für Collabs</strong><small>Auf deinem Profil und beim Entdecken sichtbar</small></span><input type="checkbox" name="collab"></label>${input('formats','Deine Collab-Formate','Co-op, Art-Tausch, Talk, Co-Working',150)}<p class="field-note">Mit Kommas trennen. Gemeinsame Formate werden bei Empfehlungen berücksichtigt.</p></div><div class="editor-panel" id="editor-links" role="tabpanel" aria-labelledby="tab-links" hidden><h3>Alles an einem Ort.</h3><p>Verbinde deine Kanäle mit deinem Profil.</p>${input('link','Website','https://…',500,'url')}${input('twitch','Twitch','https://twitch.tv/…',500,'url')}${input('youtube','YouTube','https://youtube.com/@…',500,'url')}${input('social','Weiterer Social-Link','https://…',500,'url')}</div></div><aside class="editor-live"><div class="preview-heading"><span>LIVE-VORSCHAU</span><i></i></div><div id="profileLivePreview"></div></aside></div><div class="editor-footer"><p id="editorError" role="alert"></p><div><button class="secondary editor-close" type="button">Abbrechen</button><button class="primary" type="submit" id="saveProfile">Änderungen speichern ${uiIcons.check}</button></div></div></form>`;
 const form=dialog.querySelector('form');const mediaDraft={};let imagePending=false;
 for(const key of ['name','username','role','bio','tags','pronouns','languages','schedule','formats','link','twitch','youtube','social'])form.elements[key].value=profile[key]??'';
 for(const [key,fallback] of [['theme','lilac'],['avatar','initial'],['banner','orbit']])form.elements[key].value=profile[key]||fallback;form.elements.collab.checked=!!profile.collab;
 function draft(){const data=Object.fromEntries(new FormData(form));return {...profile,...data,...mediaDraft,collab:form.elements.collab.checked}}
 function preview(){dialog.querySelector('#profileLivePreview').innerHTML=profileMarkup(draft(),{preview:true});for(const kind of ['avatar','banner']){const key=kind==='avatar'?'removeAvatar':'removeBanner';dialog.querySelector('#'+key).disabled=!mediaDraft[kind+'Upload']&&(!profile[kind+'Image']||mediaDraft[key]);}}
 for(const kind of ['avatar','banner']){const input=dialog.querySelector('#'+kind+'File'),removeKey=kind==='avatar'?'removeAvatar':'removeBanner';input.onchange=async()=>{if(!input.files?.[0]||imagePending)return;imagePending=true;form.querySelector('#saveProfile').disabled=true;dialog.querySelector('#editorError').textContent='';try{mediaDraft[kind+'Upload']=await cropImage(input.files[0],kind);mediaDraft[removeKey]=false;dialog.querySelector('#'+kind+'ImageStatus').textContent='Neuer Ausschnitt · noch nicht gespeichert';preview()}catch(error){if(error.name!=='AbortError')dialog.querySelector('#editorError').textContent=error.message}finally{input.value='';imagePending=false;form.querySelector('#saveProfile').disabled=false}};dialog.querySelector('#'+removeKey).onclick=()=>{delete mediaDraft[kind+'Upload'];mediaDraft[removeKey]=true;dialog.querySelector('#'+kind+'ImageStatus').textContent='Bild wird beim Speichern entfernt';preview()}}

 function selectTab(id){dialog.querySelectorAll('[data-editor-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.editorTab===id)));dialog.querySelectorAll('.editor-panel').forEach(panel=>panel.hidden=panel.id!=='editor-'+id)}
 dialog.querySelectorAll('[data-editor-tab]').forEach(b=>{b.onclick=()=>selectTab(b.dataset.editorTab);b.onkeydown=event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();const tabs=[...dialog.querySelectorAll('[data-editor-tab]')],next=tabs[(tabs.indexOf(b)+(event.key==='ArrowRight'?1:3))%4];selectTab(next.dataset.editorTab);next.focus()}});
 dialog.querySelectorAll('.editor-close').forEach(b=>b.onclick=()=>dialog.close());form.oninput=preview;preview();selectTab(['identity','design','collab','links'].includes(initialTab)?initialTab:'identity');
 form.onsubmit=async event=>{event.preventDefault();if(imagePending)return;const invalid=[...form.elements].find(el=>el.willValidate&&!el.validity.valid);if(invalid){selectTab(invalid.closest('.editor-panel').id.replace('editor-',''));invalid.reportValidity();return}const save=form.querySelector('#saveProfile'),error=form.querySelector('#editorError');save.disabled=true;error.textContent='';try{await onSave(draft());dialog.close()}catch(err){error.textContent=err.message}finally{save.disabled=false}};
 dialog.showModal();
}
